import unittest
from candidate import below_zero

class TestBelowZero(unittest.TestCase):
    def test_all_positive_operations(self):
        self.assertEqual(below_zero([1, 2, 3]), False)

    def test_balance_drops_below_zero(self):
        self.assertEqual(below_zero([1, 2, -4, 5]), True)

    def test_empty_list_returns_false(self):
        self.assertEqual(below_zero([]), False)

    def test_single_negative_operation(self):
        self.assertEqual(below_zero([-1]), True)

    def test_single_positive_operation(self):
        self.assertEqual(below_zero([100]), False)

    def test_balance_exactly_zero_at_boundary(self):
        self.assertEqual(below_zero([10, -10, 5]), False)

    def test_balance_touches_zero_multiple_times(self):
        self.assertEqual(below_zero([5, -5, 5, -5, 2]), False)

    def test_alternating_large_values(self):
        self.assertEqual(below_zero([1000000, -2000000, 1500000]), True)

    def test_all_negative_operations(self):
        self.assertEqual(below_zero([-1, -2, -3]), True)

    def test_none_input_raises_error(self):
        with self.assertRaises(TypeError):
            below_zero(None)

    def test_non_list_input_raises_error(self):
        with self.assertRaises(TypeError):
            below_zero(123)

    def test_list_with_string_element_raises_error(self):
        with self.assertRaises(TypeError):
            below_zero([1, "2", -3])

if __name__ == '__main__':
    unittest.main()
